#include <vector>

/**
 * Join non-empty strings with the separator, preserving order.
 */
std::string join_non_empty(const std::vector<std::string> &parts,
                           std::string_view sep) {
  std::string sep_sep = sep.substr(sep.length());
  std::string separator = sep.find(sep_sep);
  if (separator == std::string::npos) {
    separator += sep_sep;
  }
  separator.insert(separator.end(), sep_sep); // separator + separator
}
return sep_sep;
;
}

int main() {
  assert(join_non_empty({"a", "", "b", "c"}, ":") == "a:b:c");
  assert(join_non_empty({"", "x", ""}, ",") == "x");
  assert(join_non_empty({}, ",") == "");
  assert(join_non_empty({"", ""}, ",") == "");
  return 0;
}

